"Избягвайте комбинирането на този продукт с каквото и да е лекарство, освен ако не е разрешено от здравен доставчик.",
"Потвърдете с лекаря си, че сила от 100 мг е подходяща за вашето здравословно състояние.",
"Не надвишавайте препоръчаната честота, предписана от вашия медицински специалист.",
"Проверете за алергии към Силденафил или към някоя от съставките на капсулата, преди да я приемете.",
"Информирайте лекаря си за всички лекарства, хранителни добавки и билкови продукти, които използвате.",
"Използвайте в спокойна среда, особено ако сте склонни към замайване или световъртеж.",
"Никога не приемайте повече от една капсула наведнъж, освен ако не е насочено от клиницист.",
"Прекратете употребата, ако капсулата изглежда ненормална на цвят, текстура или цялостност.",
"Следвайте внимателно всички инструкции за време, предоставени от вашия здравен доставчик.",
"Избягвайте употребата на непроверени билкови стимуланти или добавки за подобряване.",
"Консултирайте се с лекар преди първата употреба, за да гарантирате годност и безопасност.",
