"Проверете визуално всяка капсула, преди да я приемете.",
"Избягвайте приемане на продукта веднага след тежка физическа активност, освен ако не е разрешено.",
"Използвайте само предписаната единична доза наведнъж.",
"Не комбинирайте с вещества, които могат да засегат стабилността на кръвното налягане.",
"Изхвърлете празните блистери отговорно, за да предотвратите случайна употреба.",
"Пийте вода редовно, освен ако лекарят ви не посъветва друго.",
"Избягвайте употреба, ако се чувствате припаднали, неразположени, трескави или прекалено уморени.",
"Консултирайте се с клиницист, ако някоя стъпка от приложението е неясна.",
"Избягвайте комбиниране с други PDE5 инхибитори, освен ако не е медицински упълномощено.",
"Спрете употребата, ако възникнат необичайни или неочаквани физически усещания.",
"Уверете се, че дозировката съответства на вашия текущ план за лечение на лекаря.",
"Потърсете медицински съвет, ако резултатите или реакциите се различават от очакванията.",
