"Пазите далеч от ръце на деца.",
"Избягвайте прекален алкохол преди приемане на капсулата, тъй като може да намали ефикасността.",
"Наблюдавайте как тялото ви реагира и се консултирайте с лекар за всякакви необичайни реакции.",
