"Избягвайте приемане на повече от предписаната дневна доза.",
"Наблюдавайте реакцията на тялото си и информирайте лекаря си за всякакви необичайни реакции.",
"Поддържайте открита комуникация с партньора си, за да намалите тревожността относно представянето.",
