"Информирайте лекаря си за всички лекарства по рецепта, без рецепта или билкови добавки, които приемате редовно.",
"Използвайте в спокойна и стабилна среда, особено ако от време на време изпитвате замайване.",
"Не приемайте повече от една таблетка едновременно, освен ако не е насочено от клиницист.",
