"Използвайте само еднократната доза, препоръчана за всеки прием, без самостоятелно коригиране.",
"Не комбинирайте със вещества, които значително променят сърдечния ритъм или кръвното налягане.",
"Изхвърлете празната блистерна опаковка безопасно, за да предотвратите случайния достъп от други.",
"Поддържайте нормална хидратация, освен ако здравният ви специалист не инструктира друго.",
