"Приемете таблетката 30–60 минути преди сексуална активност за оптимален ефект.",
"Глътнете таблетката цяла с вода; не смачквайте или дъвчете.",
"Избягвайте прекомерен алкохол, тъй като може да намали ефективността и да причини замайване.",
"Консултирайте се с лекар, ако имате сърдечно-съдови, чернодробни, бъбречни или други хронични здравословни състояния.",
"Не комбинирайте с лекарства на нитратна основа или други PDE5 инхибитори без медицински съвет.",
"Докладвайте всякакви тежки или необичайни странични ефекти, включително продължителна ерекция или болка в гърдите, незабавно.",
"Поддържайте здравословен начин на живот с редовни упражнения, балансирана диета и управление на стреса.",
"Не надвишавайте препоръчителната доза от 100 мг на повод.",
"Запазвайте таблетките в оригиналната опаковка, за да ги защитите от влага и замърсяване.",
