"Проверете всяка таблетка визуално преди да я приемете, за да се уверите в правилното състояние.",
"Избягвайте приемане на таблетката веднага след изтощителна физическа активност, освен ако не сте медицински одобрени.",
"Използвайте само предписаното количество, без самостоятелно да коригирате дозата.",
"Не смесвайте това лекарство със вещества, които значително променят сърдечния ритъм или кръвното налягане.",
"Изхвърлете опаковката правилно, за да предотвратите случайния достъп от други.",
